new='''/**
 * An issue is searchable while it and its project are live. Indexing a
 * non-live issue removes it instead, so every writer enforces the rule.
 */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (issue.archivedAt || !project || project.archivedAt) {
    await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\\n"),
    issue.projectId,
  );
}

/** A comment is searchable while it, its issue and that issue's project are live. */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  const project = issue
    ? await projectRepo.findProjectById(orgId, issue.projectId)
    : null;
  if (
    comment.archivedAt ||
    !issue ||
    issue.archivedAt ||
    !project ||
    project.archivedAt
  ) {
    await searchRepo.deleteSearchDocument(orgId, "comment", comment.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue.projectId,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (project.archivedAt) {
    await searchRepo.deleteSearchDocument(orgId, "project", project.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\\n"),
    project.id,
  );
}

const TREE_PAGE_SIZE = 100;

/** Re-evaluates every comment of one issue against the searchability rule. */
export async function indexIssueComments(
  orgId: OrgId,
  issueId: Issue["id"],
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: true,
      limit: TREE_PAGE_SIZE,
      cursor,
    });
    for (const comment of page.items) await indexComment(orgId, comment);
    cursor = page.nextCursor;
  } while (cursor);
}

/** Re-evaluates a project, all of its issues and their comments. */
export async function indexProjectTree(
  orgId: OrgId,
  projectId: Project["id"],
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) await indexProject(orgId, project);
  else await searchRepo.deleteSearchDocument(orgId, "project", projectId);

  let cursor: string | null = null;
  do {
    const page = await issueRepo.listIssues({
      orgId,
      projectId,
      includeArchived: true,
      limit: TREE_PAGE_SIZE,
      cursor,
    });
    for (const issue of page.items) {
      await indexIssue(orgId, issue);
      await indexIssueComments(orgId, issue.id);
    }
    cursor = page.nextCursor;
  } while (cursor);
}

